import{_ as e,a as o,o as a,a4 as d}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Product Inventories — Bulk Update (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-inventories-update","title":"Bulk-Update Per-Source Inventory","description":"Parent-scoped mutation. Pass a source id with a positive qty to set it, qty 0 to zero it out; sources not in the payload are left untouched. The mutation returns the updated source as a single node.","query":"mutation UpdateInventories($input: updateAdminCatalogProductInventoryInput!) {\\n  updateAdminCatalogProductInventory(input: $input) {\\n    adminCatalogProductInventory {\\n      _id\\n      sourceId\\n      sourceCode\\n      sourceName\\n      qty\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/products/1/inventories\\",\\n    \\"productId\\": 1,\\n    \\"inventories\\": {\\n      \\"1\\": 33\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateAdminCatalogProductInventory\\": {\\n      \\"adminCatalogProductInventory\\": {\\n        \\"_id\\": 1,\\n        \\"sourceId\\": 1,\\n        \\"sourceCode\\": \\"default\\",\\n        \\"sourceName\\": \\"Default\\",\\n        \\"qty\\": 33\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/inventories-update.md","filePath":"api/graphql-api/admin/catalog/products/inventories-update.md","lastUpdated":1783079210000}'),n={name:"api/graphql-api/admin/catalog/products/inventories-update.md"};function r(i,t,c,s,u,p){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="product-inventories-—-bulk-update-graphql" tabindex="-1">Product Inventories — Bulk Update (GraphQL) <a class="header-anchor" href="#product-inventories-—-bulk-update-graphql" aria-label="Permalink to &quot;Product Inventories — Bulk Update (GraphQL)&quot;">​</a></h1><p>Sets the on-hand quantity per inventory source for a product. This is a parent-scoped mutation — pass the product as <code>productId</code> inside the input. A source id with a positive quantity is set to that value, a source id with <code>0</code> is zeroed out, and any source you leave out of the map is untouched.</p><p>The <code>inventories</code> field is a map of <code>inventory_source_id</code> (as a string key) to integer quantity. The <code>id</code> field must be a placeholder IRI (<code>/api/admin/catalog/products/{productId}/inventories</code>) — it is ignored; the product is resolved from <code>productId</code>. Select <code>_id</code> on the returned node (not <code>id</code>, since this is a parent-scoped resource with no standalone route).</p><p>The mutation returns the updated source as a single node. To read the full per-source list together with the aggregate <code>totalQty</code>, query <a href="/api/graphql-api/admin/catalog/products/inventories-list.html"><code>adminCatalogProductInventories(productId:)</code></a> (a connection — <code>edges { node { _id sourceId sourceCode sourceName qty } }</code>); <code>totalQty</code> is not available on the mutation result.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/catalog/products/">Products overview</a> for how the catalog product menu fits together.</p></div><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>productId</code></td><td><code>Int!</code></td><td>yes</td><td>Parent product.</td></tr><tr><td><code>inventories</code></td><td><code>Object!</code></td><td>yes</td><td>Map of <code>inventory_source_id</code> (string key) to integer quantity (greater than or equal to 0).</td></tr><tr><td><code>id</code></td><td><code>ID!</code></td><td>yes</td><td>Placeholder IRI; ignored by the server.</td></tr></tbody></table>',8)]))}const m=e(n,[["render",r]]);export{h as __pageData,m as default};
